#include "LoRa.h"
#include "../config.mcc/mcc_generated_files/system/pins.h"
#include "../config.mcc/mcc_generated_files/uart/usart0.h"
#include "../config.mcc/mcc_generated_files/uart/usart1.h"
#include "utils.h"
#include <avr/wdt.h>
#include <util/delay.h>

uint8_t lora_count = 0;

// Envoie une chaine sur UART1 (module LoRa) en l'echoant sur UART0 (debug)
static void LoRa_SendString(const char *str) {
  while (*str) {
    while (!UART1_IsTxReady()) {
    }
    UART1_Write((uint8_t)*str);

    while (!UART0_IsTxReady()) {
    }
    UART0_Write((uint8_t)*str);

    str++;
  }
}

// Pipe tout octet recu sur UART1 (reponses/trames du module LoRa) vers UART0
// A appeler en continu (hors gate 10ms) : le CPU ne doit pas dormir entre
// deux octets sinon USART1 (sans interruption RX) en perd la plupart.
void LoRa_PollRx(void) {
  while (UART1_IsRxReady()) {
    uint8_t data = UART1_Read();

    while (!UART0_IsTxReady()) {
    }
    UART0_Write(data);
  }
}

// Envoie une commande AT et laisse le temps au module de repondre, en
// pipant sa reponse vers UART0 au fur et a mesure (sinon elle est perdue,
// LoRa_PollRx n'etant sinon appelee que dans la boucle principale).
static void LoRa_SendCommand(const char *str, uint16_t wait_ms) {
  LoRa_SendString(str);
  while (wait_ms--) {
    LoRa_PollRx();
    _delay_ms(1);
  }
}

// Faux payload pour tester la volumetrie reelle : 10 mesures
// (temperature 0.1 degre pres, decalage en minutes dans l'heure) packees
// sur 16 bits chacune (10 bits temp x10 + 6 bits minutes) = 20 octets.
#define LORA_PAYLOAD_READINGS 10

static void LoRa_BuildFakePayload(uint8_t *out) {
  for (uint8_t i = 0; i < LORA_PAYLOAD_READINGS; i++) {
    uint16_t temp_tenths = 200 + i * 10; // 20.0, 21.0, ... degres (factice)
    uint8_t minutes_ago = i * 6;         // reparties sur l'heure (factice)
    uint16_t packed = (temp_tenths << 6) | (minutes_ago & 0x3F);

    out[i * 2] = (uint8_t)(packed >> 8);
    out[i * 2 + 1] = (uint8_t)(packed & 0xFF);
  }
}

static void LoRa_SendFakePayload(void) {
  uint8_t payload[LORA_PAYLOAD_READINGS * 2];
  LoRa_BuildFakePayload(payload);

  static const char hex_digits[] = "0123456789ABCDEF";
  char cmd[18 + sizeof(payload) * 2 + 3 + 1];
  char *p = cmd;

  const char *prefix = "AT+TEST=TXLRPKT,\"";
  while (*prefix) {
    *p++ = *prefix++;
  }
  for (uint8_t i = 0; i < sizeof(payload); i++) {
    *p++ = hex_digits[payload[i] >> 4];
    *p++ = hex_digits[payload[i] & 0x0F];
  }
  *p++ = '"';
  *p++ = '\r';
  *p++ = '\n';
  *p = '\0';

  LoRa_SendString(cmd);
}

void LoRa_Init(void) {
  //   UART0_Initialize();
  //   UART0_TransmitEnable();

  //   UART1_Initialize();
  //   UART1_TransmitEnable();

  // Le Wio-E5 est long a demarrer (sans debugger attache) : on lui laisse
  // le temps de booter avant de lui parler.
  for (uint8_t i = 0; i < 20; i++) {
    wdt_reset();
    _delay_ms(100);
  }

  // Bascule le Wio-E5 en mode P2P (test)
  LoRa_SendCommand("AT+MODE=TEST\r\n", 300);

  // Config RF : doit etre IDENTIQUE a celle de LoRaListener.py (RF_CONFIG)
  // Frequence en MHz (pas en Hz)
  LoRa_SendCommand("AT+TEST=RFCFG,868.5,SF12,125,12,15,18,ON,OFF,OFF\r\n", 300);
}

void LoRa_Loop(void) {
  static bool last_tick = false;
  static uint8_t led_off_ticks = 0;

  // LoRa_Loop est appele toutes les 10ms : 100 ticks = 1s
  if (led_off_ticks > 0) {
    if (--led_off_ticks == 0) {
      IO_RED_LED_SetLow();
    }
  }

  if (Frequency_1Hz != last_tick) {
    last_tick = Frequency_1Hz;
    if (lora_count++ > 10) {
      LoRa_SendFakePayload();
      lora_count = 0;
      IO_RED_LED_SetHigh();
      led_off_ticks = 100;
    }
  }
}
